//Opens all programs under a chosen domain folder, scans them for functions
//that match a user supplied name, and prints info about the match.
//@category FunctionID



using ghidra.app.script;
using ghidra.feature.fid.service;
using ghidra.framework.model;
using ghidra.framework.model;
using ghidra.program.database;
using ghidra.program.model.listing;
using ghidra.util;
using ghidra.util.exception;
using ghidra.util.exception;

public class FindNamedFunction : GhidraScript {

	FidService service;

	/* @Override */
	protected void run()
    {
		service = new FidService();

		DomainFolder folder =
			askProjectFolder("Please select a project folder to RECURSIVELY look for a named function:");
		string name =
			askString("Please enter function name",
				"Please enter the function name you're looking for:");

		List<DomainFile> programs = new List<DomainFile>();
		findPrograms(programs, folder);
		findFunction(programs, name);
	}

	private void findFunction(List<DomainFile> programs, string name) {
		foreach (DomainFile domainFile in programs) {
			if (monitor.isCancelled()) {
				return;
			}
			Program program = null;
			try {
				program = (Program) domainFile.getDomainObject(this, false, false, monitor);
				FunctionManager functionManager = program.getFunctionManager();
				FunctionIterator functions = functionManager.getFunctions(true);
				foreach (Function function in functions) {
					if (monitor.isCancelled()) {
						return;
					}
					if (function.getName().equals(name)) {
						println("found " + name + " in " + domainFile.getPathname());
					}
				}
			}
			catch (Exception e) {
				Msg.warn(this, "problem looking at " + domainFile.getName(), e);
			}
			finally {
				if (program != null) {
					program.release(this);
				}
			}
		}
	}

	private void findPrograms(List<DomainFile> programs, DomainFolder folder)
    {
		DomainFile[] files = folder.getFiles();
		foreach (DomainFile domainFile in files) {
			if (monitor.isCancelled()) {
				return;
			}
			// Do not follow folder-links or consider program links.  Using content type
			// to filter is best way to control this.  If program links should be considered
			// "Program.class.isAssignableFrom(domainFile.getDomainObjectClass())"
			// should be used.
			if (domainFile.getContentType().equals(ProgramContentHandler.PROGRAM_CONTENT_TYPE)) {
				programs.add(domainFile);
			}
		}
		DomainFolder[] folders = folder.getFolders();
		foreach (DomainFolder domainFolder in folders) {
			if (monitor.isCancelled()) {
				return;
			}
			findPrograms(programs, domainFolder);
		}
	}
}
